edits.newText:
// B-015 / B-031: show the jump glyph when the playing track isn't
// currently visible in the browser; if it shares the same parent
// folder we probe row visibility, otherwise we consider it
// divergent.
final needsJump = playingPath != null &&
    playingPath.isNotEmpty &&
    (() {
      final playingParent = p.dirname(playingPath);
      final currentPath = path ?? '';
      if (playingParent != currentPath) return true;
      return !browserController.isTrackVisible(playingPath);
    })();
final showJumpGlyph = resolveJumpGlyphVisible(needsJump);

